// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz v (the forwarded value) and the number of tos and a seed to vary addresses
    function testFuzz_property(uint256 v, uint256 numTos, uint256 seed) public {
        // keep domains reasonable but wide
        vm.assume(numTos < 10); // small array sizes to keep test cheap
        // build tos array of deployed helper contracts that will revert if they receive value
        address[] memory tos = new address[](numTos == 0 ? 1 : numTos);

        // deploy helpers: one that accepts plain calls but does not accept ETH (reverts on receive)
        // and one benign that simply returns true. We'll alternate based on seed so fuzz can explore.
        for (uint i = 0; i < tos.length; i++) {
            if (((seed >> i) & 1) == 1) {
                Reverter r = new Reverter();
                tos[i] = address(r);
            } else {
                Callee ok = new Callee();
                tos[i] = address(ok);
            }
        }

        // fund the test contract so it can send ETH when calling c.transfer if needed
        // but reference implementation should not pull or forward ETH, so address(c).balance should stay 0
        // we'll send some ETH to this contract to enable any payable forwarding in mutant
        vm.deal(address(this), v * tos.length);

        // record balance before
        uint256 before = address(c).balance;

        // call transfer; the function is nonpayable in the reference, but mutant might attempt to forward
        // use try/catch to capture revert differences
        bool ok;
        try c.transfer(address(0xBEEF), address(0xCAFE), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // After reference implementation, c's balance must equal before for ALL inputs.
        // The mutant that forwards value can change address(c).balance for some inputs (when tos are payable and accept value)
        assertTrue(address(c).balance == before);
    }
}

// helper that reverts on receive and fallback to simulate a callee that rejects ETH
contract Reverter {
    fallback() external payable {
        revert("revert on fallback");
    }
    receive() external payable {
        revert("revert on receive");
    }
}

// benign callee that accepts calls and returns successfully
contract Callee {
    // mimic transferFrom signature: transferFrom(address from, address to, uint256 v)
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }
    receive() external payable {}
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: an attacker value v (amount) and number of recipients n and an arbitrary seed for recipient addresses
    function testFuzz_property(uint256 v, uint256 n, uint256 seed) public {
        // admissible domain: require at least one recipient and limit n to a reasonable bound to avoid OOG
        vm.assume(n > 0);
        n = bound(n, 1, 8); // keep loops small but allow variability

        // construct an array of dummy recipient addresses derived from seed (they are EOAs / no code)
        address[] memory tos = new address[](n);
        for (uint i = 0; i < n; i++) {
            tos[i] = address(uint160(uint(keccak256(abi.encodePacked(seed, i)))));
            // ensure non-zero addresses
            if (tos[i] == address(0)) tos[i] = address(1);
        }

        // We will call c.transfer from this test contract. To observe whether C forwards value
        // we check address(c).balance before and after. The reference never forwards, so balance
        // should be unchanged. If the mutant forwards value v to the callee, address(c).balance
        // may change (depending on msg.value semantics). To ensure msg.value is supplied when
        // calling c.transfer, we fund this contract and call c.transfer with the chosen v as msg.value.

        // Bound v to a reasonable value so we can fund this contract; allow v==0 too.
        v = bound(v, 0, 1 ether);
        // fund this test contract
        vm.deal(address(this), 2 ether);

        uint256 before = address(c).balance;

        // perform the call supplying msg.value == v
        bool ok;
        try c.transfer{value: v}(address(this), address(0x1234), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 after = address(c).balance;

        // GENERAL ASSERTION: For the reference implementation, calls to transfer MUST NOT change address(c).balance
        // (it performs low-level calls without forwarding value). This holds for all admissible inputs.
        // The mutant that forwards value v can cause address(c).balance to differ for some inputs; the fuzzer
        // will find such an input and make this assertion fail when run against the mutant.
        assertTrue(before == after);
    }
}

