pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, uint256 v, uint256 n) public {
        // admissible domain: non-empty _tos array length derived from n, keep it wide
        uint256 len = (n % 4) + 1; // 1..4
        address[] memory tos = new address[](len);
        for (uint i = 0; i < len; i++) {
            // fill with distinct addresses derived from caddress and i to avoid trivial duplication
            tos[i] = address(uint160(uint256(keccak256(abi.encodePacked(caddress, i)))));
        }

        // Deploy an adversarial callee that accepts ETH and accumulates it
        Receiver recv = new Receiver();
        // Use the deployed receiver's address as the external callee to exercise acceptance of value
        address callee = address(recv);

        // fund the test contract so it can forward ETH if mutant forwards value (mutant would require the caller to have ETH)
        vm.deal(address(this), v * len);

        // capture balance before call
        uint256 beforeBal = address(c).balance;

        // call transfer; we do NOT send ETH to c() itself — C.transfer executes low-level calls to callee
        // using the fuzzed parameters: from, callee, tos, v
        // ensure tos is non-empty by construction
        try c.transfer(from, callee, tos, v) {
            // success
        } catch {
            // ignore reverts for the purpose of observing balance change
        }

        // observe balance after
        uint256 afterBal = address(c).balance;

        // General rule: reference C never causes address(c).balance to increase due to its internal low-level calls
        // Assert that address(c).balance did not increase. This holds for the reference implementation for ALL inputs,
        // while the mutant that forwards {value: v} can cause address(c).balance to increase when the callee accepts ETH.
        assertTrue(afterBal <= beforeBal);
    }
}

// Adversarial helper that accepts ETH
contract Receiver {
    uint256 public received;
    receive() external payable { received += msg.value; }
}

