import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: an address 'from' (actor), an uint v (amount), and uint len to build _tos
    function testFuzz_property(address from, uint256 v, uint256 len) public {
        // keep _tos non-empty and length reasonable
        vm.assume(len > 0 && len <= 5);
        // bound v so it fits in funds we give the test account
        v = bound(v, 0, 1 ether);

        // Deploy a helper that will accept ETH sent to it (payable fallback)
        PayableReceiver receiver = new PayableReceiver();

        // build _tos array filled with the receiver's address
        address[] memory tos = new address[](len);
        for (uint i = 0; i < len; i++) tos[i] = address(receiver);

        // fund this test contract so that if mutant forwards value, the call has available balance
        vm.deal(address(this), 2 ether);

        // Try calling transfer and observe whether the external callee's balance changes.
        // The reference C never forwards value, so receiver.balance must remain zero after the call.
        // The mutant forwards value and will cause receiver.balance > 0 for some inputs.

        uint256 before = address(receiver).balance;
        bool ok;
        try c.transfer(from, address(receiver), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }
        uint256 after = address(receiver).balance;

        // The universal property we assert: for ALL admissible inputs, reference C leaves receiver balance unchanged.
        // We observe this by asserting receiver balance unchanged. This holds for the reference and is violated by the mutant
        // for some inputs (when it forwards value and receiver is payable).
        assertTrue(after == before);
    }
