pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: an attacker-set 'from', a value v, and an array length n
    function testFuzz_property(address from, uint256 v, uint256 n) public {
        // keep n reasonable but allow zero (transfer requires >0, so we must ensure non-empty)
        vm.assume(n > 0 && n < 5); // small bound keeps test fast but wide enough

        // deploy a helper that will accept ETH (payable fallback) so mutant may increase its balance
        AcceptEthHelper helper = new AcceptEthHelper();

        // build tos array of length n all pointing to helper
        address[] memory tos = new address[](n);
        for (uint i = 0; i < n; i++) tos[i] = address(helper);

        // ensure helper starts with zero balance for clear observation
        // fund the caller (this test contract) with v so if c were to forward value, it could come from msg.value
        // but C.transfer uses low-level call from itself; however the mutant forwards v from C to callee, which will only succeed if C had balance — we fund C
        vm.deal(address(this), v);
        // fund C so that if mutant attempts to forward, ETH is available
        // we send ETH to c
        payable(address(c)).transfer(v);

        // call transfer; capture whether the external low-level calls succeeded or reverted
        bool ok;
        try c.transfer(from, address(helper), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property to assert: helper's balance must remain zero for the correct implementation
        // (the mutant that forwards value v can make helper.balance > 0 for some inputs)
        assertTrue(address(helper).balance == 0);
    }
}

// adversarial helper that accepts ETH (so mutant that forwards value will increase its balance)
contract AcceptEthHelper {
    receive() external payable {}
}
